<?php
require __DIR__.'/../../includes/bootstrap.php';require_parent();$from=$_GET['de']??date('Y-m-01');$to=$_GET['ate']??date('Y-m-d');$q=db()->prepare('SELECT a.nome aluno,t.nome turma,r.tipo,r.registrado_em,r.origem FROM scp_aluno_responsavel ar JOIN scp_alunos a ON a.id=ar.aluno_id LEFT JOIN scp_turmas t ON t.id=a.turma_id LEFT JOIN scp_registros_acesso r ON r.aluno_id=a.id AND DATE(r.registrado_em) BETWEEN ? AND ? WHERE ar.responsavel_id=? AND ar.autoriza_consulta=1 ORDER BY r.registrado_em DESC');$q->execute([$from,$to,$_SESSION['responsavel_id']]);$rows=$q->fetchAll();$q=db()->prepare('SELECT a.nome,a.foto,a.qr_token,t.nome turma FROM scp_aluno_responsavel ar JOIN scp_alunos a ON a.id=ar.aluno_id LEFT JOIN scp_turmas t ON t.id=a.turma_id WHERE ar.responsavel_id=? AND ar.autoriza_consulta=1 AND a.ativo=1 ORDER BY a.nome');$q->execute([$_SESSION['responsavel_id']]);$children=$q->fetchAll();layout_header('Portal do responsável');?>
<h1>Olá, <?=e($_SESSION['name'])?></h1><p class="text-muted">Seus alunos e movimentações</p><div class="family-cards"><?php foreach($children as $child):?><article><?php if($child['foto']):?><img src="<?=e($child['foto'])?>" alt="Foto de <?=e($child['nome'])?>"><?php endif?><div><strong><?=e($child['nome'])?></strong><span><?=e($child['turma']??'Sem turma')?></span></div><a class="btn btn-primary" href="<?=e(url('cracha.php?token='.$child['qr_token']))?>">Abrir crachá</a></article><?php endforeach?></div><form class="row g-2 my-4"><div class="col"><label class="form-label">De</label><input type="date" class="form-control" name="de" value="<?=e($from)?>"></div><div class="col"><label class="form-label">Até</label><input type="date" class="form-control" name="ate" value="<?=e($to)?>"></div><div class="col-auto align-self-end"><button class="btn btn-primary">Filtrar</button></div></form><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Aluno</th><th>Turma</th><th>Movimento</th><th>Data e hora</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['aluno'])?></td><td><?=e($r['turma']??'-')?></td><td><?=e($r['tipo']??'-')?></td><td><?=e($r['registrado_em']?date('d/m/Y H:i',strtotime($r['registrado_em'])):'Sem registros')?></td></tr><?php endforeach?></tbody></table></div></div><?php layout_footer();
